from math import gcd

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(x for row in a for x in row).most_common(1)[0][0]
    # Detect a full uniform separator line (distinct from the background).
    candidates=[]
    for r,row in enumerate(a):
        if len(set(row))==1 and row[0]!=bg:
            candidates.append(('h',r,row[0]))
    for c in range(w):
        col=[a[r][c] for r in range(h)]
        if len(set(col))==1 and col[0]!=bg:
            candidates.append(('v',c,col[0]))
    if not candidates:
        return a
    # The separator axis is identified by the most separator lines.
    orient=max(('h','v'), key=lambda o:sum(x[0]==o for x in candidates))
    lines=sorted(x[1] for x in candidates if x[0]==orient)
    n=h if orient=='h' else w
    if len(lines)>1:
        period=0
        for x,y in zip(lines,lines[1:]): period=gcd(period,y-x)
        origin=0
    else:
        k=lines[0]
        before_len=k
        after_len=n-k-1
        def signal_count(start,end):
            if orient=='h':
                return sum(x!=bg for row in a[start:end] for x in row)
            return sum(a[r][c]!=bg for r in range(h) for c in range(start,end))
        before=signal_count(0,k)
        after=signal_count(k+1,n)
        if before>=after:
            period=before_len; origin=0
        else:
            period=after_len; origin=k+1
    if period<=0: return a
    if orient=='h':
        src=[row[:] for row in a]
        for r in range(h):
            if r in lines: continue
            sr=origin+((r-origin)%period)
            if 0<=sr<h and sr not in lines:
                a[r]=src[sr][:]
    else:
        src=[row[:] for row in a]
        for c in range(w):
            if c in lines: continue
            sc=origin+((c-origin)%period)
            if 0<=sc<w and sc not in lines:
                for r in range(h): a[r][c]=src[r][sc]
    return a
''')
